SourceCode.Declaration:
/// <summary>
/// Controller for the scheduled batch posting of recurring free text invoices.
/// Invoked from the "Post in Batch" menu item under
/// Accounts Receivable > Invoices > Recurring Invoices > Post Recurring Invoices.
/// Mirrors the parallel bundle-splitting pattern of <c>CustRecurrenceInvoicePostController</c>
/// but operates across all unposted <c>CustRecurrenceInvoiceGroup</c> records that satisfy
/// the date-range query on <c>METCustRecurrenceInvoiceBatchPostContract</c>.
/// </summary>
public class METCustRecurrenceInvoiceBatchPostController extends SysOperationServiceController implements BatchRetryable
{
    private RecId startBundle;
    private RecId endBundle;

}

Method.Source:
/// <summary>
/// Recurring invoice posting is not safely retryable.
/// </summary>
[Hookable(false)]
public boolean isRetryable()
{
    return false;
}

/// <summary>
/// Forces the operation to always run in batch mode.
/// The "Run in background > Batch processing" checkbox will be checked
/// and disabled so the user cannot uncheck it.
/// </summary>
/// <returns>Always <c>true</c>.</returns>
public boolean mustGoBatch()
{
    return true;
}

/// <summary>
/// Constructs the controller wired to <c>splitInvoiceBundles</c> running as a scheduled batch.
/// The split method fans out per-group child tasks at runtime.
/// </summary>
public static METCustRecurrenceInvoiceBatchPostController construct()
{
    return new METCustRecurrenceInvoiceBatchPostController(
            classStr(METCustRecurrenceInvoiceBatchPostController),
            methodStr(METCustRecurrenceInvoiceBatchPostController, splitInvoiceBundles),
            SysOperationExecutionMode::ScheduledBatch);
}

/// <summary>
/// Entry point invoked by the "Post in Batch" action menu item.
/// Displays the batch scheduling dialog, allowing the user to configure
/// a recurrence schedule and filter groups via "Records to include"
/// (generation date and invoice date). No record context is required.
/// </summary>
/// <param name="args">Args passed from the menu item.</param>
public static void main(Args args)
{
    METCustRecurrenceInvoiceBatchPostController controller;

    controller = METCustRecurrenceInvoiceBatchPostController::construct();
    controller.parmShowDialog(true);
    controller.parmDialogCaption("@AccountsReceivable:PostRecurrentFreeTextInvoice");
    controller.startOperation();
}

/// <summary>
/// Runs as the top-level batch task. Resolves all unposted
/// <c>CustRecurrenceInvoiceGroup</c> records from the contract query and,
/// for each group, splits its unposted invoices into bundles of at least
/// <c>SalesParameters.OrderBatchTaskSize</c> (minimum 100). Each bundle is
/// registered as a child batch task that delegates to the standard
/// <c>CustRecurrenceInvoicePostController.executeParallelTaskForRecurrenceInvoicePosting</c>.
/// </summary>
/// <param name="_contract">
///     Contract carrying the packed query used to filter recurring invoice groups
///     by generation date and invoice date.
/// </param>
internal void splitInvoiceBundles(METCustRecurrenceInvoiceBatchPostContract _contract)
{
    const int MinBundleSize = 100;
    int bundleSize = SalesParameters::find().OrderBatchTaskSize;

    if (bundleSize < MinBundleSize)
    {
        bundleSize = MinBundleSize;
    }

    BatchHeader batchHeader = BatchHeader::getCurrentBatchHeader();

    if (batchHeader == null)
    {
        batchHeader = BatchHeader::construct();
    }

    QueryRun                    queryRun = new QueryRun(_contract.getQuery());
    CustRecurrenceInvoiceGroup  custRecurrenceInvoiceGroup;
    RecurrenceInvoice           invoice;
    CustInvoiceTable            custInvoice;

    while (queryRun.next())
    {
        custRecurrenceInvoiceGroup = queryRun.get(tableNum(CustRecurrenceInvoiceGroup));

        // Guard: skip any group already posted at execution time.
        if (custRecurrenceInvoiceGroup.Posted != NoYes::No)
        {
            continue;
        }

        Counter i;
        RecId   lastBundle;
        boolean hasInvoicesToProcess;

        startBundle = 0;
        endBundle   = 0;

        while select RecId from invoice
                order by invoice.RecId asc
                where invoice.CustRecurrenceInvoiceGroup == custRecurrenceInvoiceGroup.RecId
                exists join custInvoice
                    where custInvoice.RecId == invoice.CustInvoiceTable
                        && custInvoice.Posted == NoYes::No
        {
            i++;

            if (i == 1)
            {
                startBundle = invoice.RecId;
            }

            if (i >= bundleSize)
            {
                endBundle = invoice.RecId;
                i = 0;

                batchHeader.addTask(
                        this.cloneForSubProcess(custRecurrenceInvoiceGroup),
                        this.parmCurrentBatch().RecId);
            }

            lastBundle          = invoice.RecId;
            hasInvoicesToProcess = true;
        }

        // Flush any remaining invoices that did not fill a complete bundle,
        // or create a single empty-range task when the group has no invoices
        // (so the group status is still evaluated by the service).
        boolean shouldCreateBundle = (i > 0 || !hasInvoicesToProcess);
        if (shouldCreateBundle)
        {
            endBundle = lastBundle;

            batchHeader.addTask(
                    this.cloneForSubProcess(custRecurrenceInvoiceGroup),
                    this.parmCurrentBatch().RecId);
        }
    }

    batchHeader.save();
}

/// <summary>
/// Creates a child <c>CustRecurrenceInvoicePostController</c> task scoped to
/// the current <c>startBundle</c> / <c>endBundle</c> range for the given group.
/// Reuses the standard parallel execution path so no custom service logic is
/// required for the actual posting work.
/// </summary>
/// <param name="_group">The recurring invoice group to post.</param>
/// <returns>
///     A <c>CustRecurrenceInvoicePostController</c> ready to be added as a batch task.
/// </returns>
private CustRecurrenceInvoicePostController cloneForSubProcess(CustRecurrenceInvoiceGroup _group)
{
    CustRecurrenceInvoicePostController controller = new CustRecurrenceInvoicePostController(
            classStr(CustRecurrenceInvoicePostController),
            methodStr(CustRecurrenceInvoicePostController, executeParallelTaskForRecurrenceInvoicePosting),
            SysOperationExecutionMode::Synchronous);

    CustRecurrenceInvoicePostContract dataContract =
            controller.getDataContractInfoObject().dataContractObject() as CustRecurrenceInvoicePostContract;

    dataContract.parmStartBundle(startBundle);
    dataContract.parmEndBundle(endBundle);
    dataContract.parmCustRecurrenceInvoiceGroup(_group);
    dataContract.parmRecurrenceInvoicePost(NoYes::Yes);
    dataContract.parmRecurrencePostTransfer(NoYes::No);
    dataContract.parmCheckRecurrenceInvoice(NoYes::No);
    dataContract.parmValidateInSandbox(NoYes::No);

    return controller;
}
